\left[ 
\frac{1}{G} \sum_{i=1}^{G} 
\left( \frac{ \pi_{\theta} (y_i | x) }{ \pi_{\theta_\text{old}} (y_i | x)} \right)^{\frac{1}{|y_i|}} \widehat{A}_{i} 
\cdot \frac{1}{|y_i|} \sum_{t=1}^{|y_i|} \nabla_{\theta} \log \pi_{\theta} (y_{i,t} | x, y_{i,<t}) 
